{
  "id": "ww-00030",
  "version": "0.1",
  "concept_id": "ww-00030",
  "blueprint_id": "ww-00030",
  "color_palette": [
    {
      "name": "Axiom Void",
      "hex": "#0A0C14",
      "usage": "Primary deep-space background for hero sections, navigation bar, footer, and full-bleed narrative transition panels \u2014 anchors the AI Lab's nocturnal intelligence throughout the scroll journey"
    },
    {
      "name": "Coldframe White",
      "hex": "#EDF1F7",
      "usage": "Primary surface for room cards, article list items, pricing panels, and body text blocks on dark backgrounds \u2014 provides crisp technical contrast against Axiom Void"
    },
    {
      "name": "Neural Violet",
      "hex": "#7C3AED",
      "usage": "Primary brand accent for CTA buttons, active navigation states, hover highlights on feature grid items, and pricing tier emphasis \u2014 the signature hue that defines Axiom's forward-facing identity"
    },
    {
      "name": "Synapse Cyan",
      "hex": "#00D4E8",
      "usage": "Secondary accent for node-graph decorative elements, eyebrow label underlines, interactive hover glows on cards, and key data callouts in the offers and accommodations pages"
    },
    {
      "name": "Circuit Slate",
      "hex": "#1E2535",
      "usage": "Mid-depth surface for alternating scroll sections, contact block background, map block overlay, and floating panel containers \u2014 creates layered depth without breaking the dark palette"
    },
    {
      "name": "Precision Mist",
      "hex": "#8B9BB8",
      "usage": "Secondary body text, metadata, caption text, and subdued UI labels \u2014 used for dates in the journal article list, room spec details, and form field placeholder text"
    },
    {
      "name": "Pulse Amethyst",
      "hex": "#C084FC",
      "usage": "Gradient terminus paired with Neural Violet on hero display text and CTA hover states \u2014 adds luminous depth to large typographic moments and abstract neural background patterns"
    },
    {
      "name": "Signal Graphite",
      "hex": "#2E3A50",
      "usage": "Border lines, technical diagram strokes, card dividers, and subtle grid rule overlays \u2014 the structural color that echoes circuit-board precision across all page surfaces"
    }
  ],
  "typography": {
    "heading_font": "Archivo",
    "body_font": "IBM Plex Sans",
    "accent_font": "IBM Plex Mono",
    "heading_treatment": "Archivo at display scale (H1 64\u201380px, H2 40\u201352px, H3 28\u201334px) in Black and Bold weights, uppercase or sentence case depending on hierarchy level \u2014 H1 hero titles in tight negative tracking (\u22120.03em) to convey precision engineering; H2 section titles in semibold with moderate tracking (\u22120.01em); all headings rendered in Coldframe White or Neural Violet-to-Pulse Amethyst gradient on dark surfaces for maximum luminous impact.",
    "body_treatment": "IBM Plex Sans at 16\u201318px with 1.65 line-height and comfortable measure (65\u201375ch), set in Coldframe White on dark surfaces and Axiom Void on light card surfaces \u2014 the humanist-technical register of IBM Plex Sans mirrors the hotel's balance of warmth and intelligence, used for all section descriptions, room copy, article body, and form labels.",
    "accent_treatment": "IBM Plex Mono in uppercase at 11\u201313px with wide letter-spacing (0.12\u20130.18em) exclusively for eyebrow labels, stat badges, room spec metadata, pricing tier tags, journal article category chips, and form field micro-labels \u2014 rendered in Synapse Cyan on dark surfaces or Precision Mist on mid-depth panels, never exceeding 14px, functioning as the system's technical annotation layer."
  },
  "pages": [
    {
      "slug": "home",
      "page_level_design_instruction": "The Axiom Hotel homepage is a three-act storytelling scroll built on a nocturnal deep-space canvas, delivering an unmistakably AI Lab experience \u2014 intelligent, precise, and future-facing. The page reads as a single continuous narrative: an immersive hero that asserts brand dominance, a technical feature grid that decodes the hotel's core pillars, and a high-voltage CTA close that converts curiosity into action.\n\nSURFACE AND COLOR LOGIC: The page never breaks to white or light backgrounds. Section 1 (Hero) sits on Axiom Void (#0A0C14) \u2014 the absolute dark anchor. Section 2 (Feature Grid) shifts to Circuit Slate (#1E2535) \u2014 a mid-depth surface that creates layered depth without disrupting the dark palette continuity. Section 3 (CTA) returns to Axiom Void for a bookend effect, but is saturated with a full-bleed Neural Violet (#7C3AED) panel that occupies the entire section background \u2014 this is the most chromatic moment on the page and signals urgency. Synapse Cyan (#00D4E8) is used as a structural accent throughout: node-graph decorative line-work, eyebrow underlines, and glowing card borders. Pulse Amethyst (#C084FC) appears exclusively in gradient typography moments on the hero headline. Signal Graphite (#2E3A50) defines all border strokes, card dividers, and technical diagram rules. Precision Mist (#8B9BB8) handles all metadata, captions, and subdued labels.\n\nTYPOGRAPHIC HIERARCHY: Archivo Black at 72px (tight \u22120.03em tracking) owns the hero headline \u2014 a display-scale typographic stunt. IBM Plex Mono in uppercase at 12px / 0.16em letter-spacing handles all eyebrow labels in Synapse Cyan. IBM Plex Sans at 18px / 1.65 line-height handles body and subheadlines in Coldframe White. Section 2 card titles use Archivo Bold at 28px. The CTA section headline uses Archivo Black at 52px in Coldframe White.\n\nSIGNATURE MOMENT: The page's defining visual move lives in Section 1 \u2014 the hero headline \"Where Every Stay Is Engineered for Excellence\" is rendered at maximum display scale (72\u201380px Archivo Black) with the word \"Engineered\" breaking into a Neural Violet \u2192 Pulse Amethyst horizontal gradient, while a full-bleed abstract neural node-graph pattern (fine white/cyan lines connecting floating data-point nodes) pulses behind the text as a layered background texture. The node graph is not tucked into a corner \u2014 it dominates the entire hero viewport, bleeding edge-to-edge behind the text stack, with nodes concentrated toward the upper-right quadrant and thinning toward the lower-left where the text block anchors. This move is inevitable for the AI Lab aesthetic: the node graph is its primary visual_cue, and placing it at full amplitude in the hero establishes the brand's technical intelligence before a single word is read.\n\nDENSITY AND WHITESPACE RHYTHM: Section 1 is sparse and monumental \u2014 maximum vertical padding (160px top / 140px bottom), text anchored left at 55% column width, right half occupied by the node-graph field. Section 2 is denser \u2014 three cards in a horizontal grid with 40px gaps, moderate vertical padding (80px top/bottom), each card carrying a technical diagram icon and spec metadata. Section 3 is compact and centred \u2014 tight vertical padding (100px top/bottom), centred type stack, two CTAs side by side, and the Neural Violet full-bleed background doing all the heavy lifting.\n\nLAYOUT FAMILY \u2014 STORYTELLING SCROLL: Each section functions as a distinct narrative beat. Section 1 = Brand declaration. Section 2 = Proof of promise. Section 3 = Invitation to act. Large narrative transitions between sections are marked by a 2px Signal Graphite horizontal rule with a small Synapse Cyan node-dot at its midpoint \u2014 a recurring structural device that echoes circuit-board precision and signals the scroll rhythm without using whitespace alone.\n\nRESPONSIVE BEHAVIOR: On mobile (< 768px), the hero text stack expands to full width with the node-graph pattern as a full-bleed background overlay at reduced opacity (0.4) so text remains legible. The feature grid collapses from 3 columns to a single stacked column with 32px gaps. The CTA section's two buttons stack vertically with 16px gap. All padding values halve on mobile. Archivo hero headline scales down to 48px on mobile, 60px on tablet.",
      "section_design_plans": [
        {
          "id": "home-section-1",
          "nl_prompt": "SECTION TYPE: Hero. INTENT: Establish brand identity with a bold, intelligent first impression that pulls the visitor into the Axiom world.\n\nLAYOUT AND GRID: Full-viewport-height section (min-height 100vh) on an Axiom Void (#0A0C14) background. Use a 12-column grid. The text content block occupies columns 1\u20137 (left-aligned, with 80px left padding on desktop). Columns 8\u201312 are visually 'owned' by the neural node-graph background element \u2014 no text intrudes there. The node-graph pattern is a full-bleed layer behind everything, rendered as fine Signal Graphite (#2E3A50) and Synapse Cyan (#00D4E8) lines connecting abstract floating node-dots, with node density concentrated in the upper-right quadrant (columns 8\u201312, top 60% of viewport) and fading/thinning toward the lower-left where the text block sits. The pattern extends edge-to-edge of the viewport \u2014 it is not contained in a box. A subtle radial gradient vignette in Axiom Void overlays the left half of the node-graph at ~60% opacity to ensure text legibility without fully suppressing the pattern.\n\nEYEBROW: IBM Plex Mono, uppercase, 12px, letter-spacing 0.16em, color Synapse Cyan (#00D4E8). Text: 'WELCOME TO AXIOM HOTEL'. Positioned above the headline with 0 0 12px 0 margin. A 24px-wide, 2px-tall Synapse Cyan underline rule sits beneath the eyebrow text, left-aligned to the text start \u2014 not full-width, just a short technical annotation mark.\n\nHEADLINE: Archivo Black, 76px, tracking \u22120.03em, line-height 1.05. Text: 'Where Every Stay Is Engineered for Excellence'. Rendered across two or three lines depending on natural wrapping. The word 'Engineered' is styled with a left-to-right horizontal gradient from Neural Violet (#7C3AED) to Pulse Amethyst (#C084FC) \u2014 this is the SIGNATURE MOMENT of the entire page. All other words in the headline are Coldframe White (#EDF1F7). The gradient word should be on its own visual line if possible (natural line break encouraged by the column width constraint).\n\nSUBHEADLINE: IBM Plex Sans, 18px, weight 400, line-height 1.65, color Precision Mist (#8B9BB8). Text: 'A boutique business hotel designed with the precision of the future and the warmth of true hospitality.' Max-width 520px. Margin-top 24px from headline.\n\nCTA ROW: Two buttons, left-aligned, flex row, gap 16px, margin-top 40px. Primary CTA 'Explore Rooms': solid Neural Violet (#7C3AED) background, Coldframe White label in IBM Plex Sans SemiBold 15px, padding 14px 32px, no border-radius (sharp rectangular corners to reinforce technical precision). Secondary CTA 'View Current Offers': transparent background, 1.5px solid Signal Graphite (#2E3A50) border, Coldframe White label, same padding \u2014 on hover, border transitions to Synapse Cyan with a faint Synapse Cyan glow (box-shadow: 0 0 12px rgba(0,212,232,0.35)).\n\nVERTICAL RHYTHM: 160px padding-top, 140px padding-bottom. The text stack (eyebrow + headline + subheadline + CTAs) is vertically centered in the viewport, anchored slightly above true center (top offset ~45%) to give the node-graph field breathing room below.\n\nDECORATIVE DETAIL: A single 1px horizontal Signal Graphite line runs the full width of the section at the very bottom, with a 6px-diameter Synapse Cyan filled circle centered on it \u2014 this is the narrative transition device that appears between all sections on the page.\n\nRESPONSIVE: Mobile \u2014 headline scales to 48px, text block goes full width (columns 1\u201312) with 24px horizontal padding, node-graph pattern remains full-bleed at 35% opacity overlay so text is legible, CTAs stack vertically with 12px gap."
        },
        {
          "id": "home-section-2",
          "nl_prompt": "SECTION TYPE: Feature Grid. INTENT: Decode the three core pillars of the Axiom experience \u2014 Intelligent Workspaces, Curated Calm, Frictionless Service \u2014 in a technically precise, scannable grid that reads as a system spec sheet rather than a generic card layout.\n\nSURFACE: Full-width section on Circuit Slate (#1E2535) background. This mid-depth surface creates a clear visual layer shift from the Axiom Void hero above. Vertical padding: 88px top, 88px bottom.\n\nEYEBROW: IBM Plex Mono, uppercase, 12px, letter-spacing 0.16em, color Synapse Cyan (#00D4E8). Text: 'THE AXIOM DIFFERENCE'. Left-aligned to the grid's left edge (column 1). Short 24px Synapse Cyan underline rule beneath, matching the hero eyebrow treatment for cross-section consistency.\n\nHEADLINE: Archivo Bold, 44px, tracking \u22120.01em, line-height 1.15, color Coldframe White (#EDF1F7). Text: 'Built for the Way You Work and Rest'. Left-aligned. Max-width 600px. Margin-top 12px from eyebrow, margin-bottom 56px from the card grid \u2014 this generous gap separates the section header from the cards, creating a masthead-style header moment before the grid begins.\n\nCARD GRID: Three equal-width columns (columns 1\u20134, 5\u20138, 9\u201312 on a 12-col grid), 32px column gap. Each card is a floating panel: Circuit Slate base with a 1.5px Signal Graphite (#2E3A50) border on all sides, and a top-edge 2px Synapse Cyan (#00D4E8) accent line (full card width) that functions as a 'live' indicator \u2014 a technical diagram motif. Card background: slightly lighter than Circuit Slate, using a subtle 4% Coldframe White tint (approximately #222A3A) to lift the card surface off the section background. Card padding: 36px on all sides. No border-radius \u2014 sharp corners throughout.\n\nCARD INTERNAL ANATOMY (each card, top to bottom):\n1. TECHNICAL ICON / DIAGRAM: A small abstract technical glyph (16\u00d716px bounding box) in Synapse Cyan \u2014 for card 1 a node-cluster symbol, for card 2 a waveform/sine line, for card 3 a branching flow-path. Positioned top-left of card content area. Below it, a 1px Signal Graphite horizontal rule spanning the full card interior width, with 16px margin below the icon and 16px above the title \u2014 this rule functions as a technical annotation separator.\n2. CARD TITLE: Archivo Bold, 26px, tracking 0, line-height 1.2, color Coldframe White (#EDF1F7). Left-aligned.\n3. CARD DESCRIPTION: IBM Plex Sans, 16px, weight 400, line-height 1.65, color Precision Mist (#8B9BB8). Left-aligned. Margin-top 12px from title.\n4. CARD METADATA TAG (bottom of card, pushed to bottom via flex column + margin-top auto): IBM Plex Mono uppercase, 11px, letter-spacing 0.14em, color Synapse Cyan (#00D4E8). For card 1: 'WORKSPACE INTEL'. For card 2: 'DESIGN SYSTEM'. For card 3: 'SERVICE PROTOCOL'. This tag functions as a system classification label \u2014 a spec-sheet annotation.\n\nHOVER STATE: On card hover, the top-edge Synapse Cyan line brightens (opacity 1 \u2192 full saturation), and a faint Synapse Cyan glow appears on the card border (box-shadow: 0 0 16px rgba(0,212,232,0.2)). The card title shifts from Coldframe White to Synapse Cyan. Transition: 200ms ease.\n\nSECTION BOTTOM: The same Signal Graphite horizontal rule with centered Synapse Cyan node-dot transition device appears at the section's bottom edge, consistent with the hero section's closing rule.\n\nRESPONSIVE: Tablet \u2014 2 columns (first two cards side by side, third card full-width below). Mobile \u2014 single column stack, each card full-width, 24px vertical gap between cards."
        },
        {
          "id": "home-section-3",
          "nl_prompt": "SECTION TYPE: CTA. INTENT: Convert engaged visitors into bookers or inquiry leads. This is the page's most chromatic, high-energy moment \u2014 a saturated Neural Violet full-bleed panel that breaks the dark-surface alternation and signals urgency.\n\nSURFACE: Full-width section with Neural Violet (#7C3AED) as the solid full-bleed background. This is the only section on the page with a saturated color background \u2014 it is intentional and unmissable. A subtle abstract neural node-graph pattern (matching the hero's node-graph motif but at very low opacity \u2014 ~8% Coldframe White lines) overlays the Neural Violet background, creating depth and reinforcing the AI Lab visual language without competing with the text. Vertical padding: 104px top, 104px bottom.\n\nCOMPOSITION: Centred layout. All content is centred horizontally within the viewport. This is one of the few centred compositions on the page \u2014 justified by the CTA section's role as a terminal, high-intention moment where symmetry conveys resolve and finality, consistent with the layout_family's 'impact block' structure cue.\n\nEYEBROW: IBM Plex Mono, uppercase, 12px, letter-spacing 0.16em, color Pulse Amethyst (#C084FC). Text: 'READY TO EXPERIENCE AXIOM?'. Centred. A 32px-wide, 2px-tall Pulse Amethyst underline rule centred beneath the eyebrow text \u2014 slightly wider than the hero and feature grid eyebrow rules to signal escalation.\n\nHEADLINE: Archivo Black, 56px, tracking \u22120.02em, line-height 1.08, color Coldframe White (#EDF1F7). Text: 'Your Next Stay Starts Here'. Centred. Margin-top 16px from eyebrow. This headline is intentionally shorter and punchier than the hero headline \u2014 it reads as a command, not a description.\n\nSUBHEADLINE: IBM Plex Sans, 18px, weight 400, line-height 1.6, color Coldframe White at 85% opacity (rgba(237,241,247,0.85)). Text: 'Explore tailored packages, premium rooms, and exclusive offers crafted for business travelers.' Centred. Max-width 540px, centred in viewport. Margin-top 20px from headline.\n\nCTA ROW: Two buttons, centred flex row, gap 20px, margin-top 44px. Primary CTA 'Book Your Stay': Coldframe White (#EDF1F7) background, Axiom Void (#0A0C14) label text in IBM Plex Sans SemiBold 15px, padding 16px 40px, sharp rectangular corners. On hover, background transitions to Pulse Amethyst (#C084FC) with Axiom Void text \u2014 a luminous inversion that uses the palette expressively. Secondary CTA 'See Our Offers': transparent background, 1.5px solid Coldframe White border, Coldframe White label, same padding. On hover, border and label transition to Pulse Amethyst.\n\nDECORATIVE DETAIL: Two thin horizontal Signal Graphite (#2E3A50) lines \u2014 one at 20% opacity \u2014 run the full section width at the top and bottom edges of the section, each with a small Pulse Amethyst node-dot at center. This maintains the page's recurring circuit-rule transition device while adapting it to the violet surface context.\n\nRESPONSIVE: Mobile \u2014 headline scales to 40px, subheadline max-width becomes 100% with 24px horizontal padding, CTA buttons stack vertically (full-width on mobile, 280px max-width each) with 14px gap."
        }
      ]
    },
    {

input.content:
/* ============================================================
   AXIOM HOTEL — Design System
   ============================================================ */

:root {
  --c-void: #0A0C14;
  --c-coldframe: #EDF1F7;
  --c-violet: #7C3AED;
  --c-cyan: #00D4E8;
  --c-slate: #1E2535;
  --c-mist: #8B9BB8;
  --c-amethyst: #C084FC;
  --c-graphite: #2E3A50;

  --c-card: #222A3A;

  --f-heading: 'Archivo', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-body: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Consolas, monospace;

  --grid-max: 1280px;
  --grid-pad: 80px;

  --ease: cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--f-body);
  background: var(--c-void);
  color: var(--c-coldframe);
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
  color: inherit;
}

img, svg {
  display: block;
  max-width: 100%;
}

ul {
  list-style: none;
}

/* ============================================================
   Layout primitives
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--grid-max);
  margin: 0 auto;
  padding: 0 var(--grid-pad);
}

@media (max-width: 1024px) {
  :root { --grid-pad: 48px; }
}
@media (max-width: 768px) {
  :root { --grid-pad: 24px; }
}

/* Transition rule: thin Signal Graphite line with cyan node-dot */
.rule-divider {
  position: relative;
  width: 100%;
  height: 1px;
  background: var(--c-graphite);
}
.rule-divider::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-cyan);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

/* ============================================================
   Top navigation bar
   ============================================================ */

.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 12, 20, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--c-graphite);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: 18px;
  letter-spacing: -0.02em;
  color: var(--c-coldframe);
  text-transform: uppercase;
}

.brand-mark {
  width: 28px;
  height: 28px;
}

.brand-tag {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  color: var(--c-cyan);
  text-transform: uppercase;
  margin-left: 4px;
  padding-left: 12px;
  border-left: 1px solid var(--c-graphite);
}

.nav-links {
  display: flex;
  gap: 36px;
  align-items: center;
}

.nav-links a {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-mist);
  position: relative;
  padding: 8px 0;
  transition: color 200ms var(--ease);
}

.nav-links a:hover {
  color: var(--c-coldframe);
}

.nav-links a.active {
  color: var(--c-cyan);
}

.nav-links a.active::after {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 0;
  width: 100%;
  height: 1px;
  background: var(--c-cyan);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

.nav-cta {
  font-family: var(--f-body);
  font-weight: 600;
  font-size: 14px;
  background: var(--c-violet);
  color: var(--c-coldframe);
  padding: 10px 22px;
  transition: background 200ms var(--ease);
}

.nav-cta:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
}

.nav-toggle {
  display: none;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

@media (max-width: 900px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .nav-toggle { display: inline-block; }
}

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--f-body);
  font-weight: 600;
  font-size: 15px;
  padding: 14px 32px;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: all 200ms var(--ease);
  text-transform: none;
  letter-spacing: 0;
}

.btn--primary {
  background: var(--c-violet);
  color: var(--c-coldframe);
}

.btn--primary:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
  box-shadow: 0 0 24px rgba(192, 132, 252, 0.35);
}

.btn--ghost {
  background: transparent;
  border-color: var(--c-graphite);
  color: var(--c-coldframe);
}

.btn--ghost:hover {
  border-color: var(--c-cyan);
  color: var(--c-cyan);
  box-shadow: 0 0 12px rgba(0, 212, 232, 0.35);
}

.btn--invert {
  background: var(--c-coldframe);
  color: var(--c-void);
}

.btn--invert:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
}

.btn--ghost-light {
  background: transparent;
  border-color: var(--c-coldframe);
  color: var(--c-coldframe);
}

.btn--ghost-light:hover {
  background: rgba(237, 241, 247, 0.1);
  border-color: var(--c-amethyst);
  color: var(--c-amethyst);
}

.btn--inverse {
  background: var(--c-void);
  color: var(--c-coldframe);
}

.btn--inverse:hover {
  background: var(--c-graphite);
  border-color: var(--c-coldframe);
}

.btn--block {
  width: 100%;
}

.btn-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 40px;
}

.btn-row--center {
  justify-content: center;
}

@media (max-width: 600px) {
  .btn-row { flex-direction: column; }
  .btn { width: 100%; }
}

/* ============================================================
   Eyebrow + headline patterns
   ============================================================ */

.eyebrow {
  font-family: var(--f-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: inline-block;
}

.eyebrow--rule::after {
  content: "";
  display: block;
  width: 28px;
  height: 2px;
  background: var(--c-cyan);
  margin-top: 8px;
  box-shadow: 0 0 6px rgba(0, 212, 232, 0.6);
}

.eyebrow--mist {
  color: var(--c-mist);
}

.eyebrow--amethyst {
  color: var(--c-amethyst);
}
.eyebrow--amethyst.eyebrow--rule::after {
  background: var(--c-amethyst);
  width: 32px;
  box-shadow: 0 0 6px rgba(192, 132, 252, 0.6);
}

.eyebrow--white {
  color: rgba(237, 241, 247, 0.8);
}
.eyebrow--white.eyebrow--rule::after {
  background: var(--c-coldframe);
  width: 32px;
  box-shadow: 0 0 6px rgba(237, 241, 247, 0.4);
}

.h-display {
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: clamp(40px, 6.5vw, 76px);
  line-height: 1.05;
  letter-spacing: -0.03em;
  color: var(--c-coldframe);
}

.h-1 {
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: clamp(36px, 5.5vw, 64px);
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--c-coldframe);
}

.h-2 {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: clamp(32px, 4vw, 44px);
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--c-coldframe);
}

.h-3 {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: clamp(22px, 2.4vw, 28px);
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--c-coldframe);
}

.text-grad {
  background: linear-gradient(90deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

.subhead {
  font-family: var(--f-body);
  font-size: 18px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 560px;
}

.subhead--white {
  color: rgba(237, 241, 247, 0.85);
}

.lead-body {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 600px;
}

/* ============================================================
   Hero — Home
   ============================================================ */

.hero {
  position: relative;
  min-height: 100vh;
  background: var(--c-void);
  overflow: hidden;
  display: flex;
  align-items: center;
  padding: 160px 0 140px;
  isolation: isolate;
}

.hero-pattern {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.hero-pattern svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-pattern::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 80% at 0% 50%,
    rgba(10, 12, 20, 0.92) 0%,
    rgba(10, 12, 20, 0.6) 40%,
    rgba(10, 12, 20, 0) 80%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.hero .eyebrow {
  margin-bottom: 24px;
}

.hero-headline {
  margin-top: 0;
}

.hero-sub {
  margin-top: 24px;
  max-width: 520px;
}

@media (max-width: 768px) {
  .hero { padding: 96px 0 80px; min-height: auto; }
  .hero-pattern { opacity: 0.45; }
}

/* ============================================================
   Section base + alternation
   ============================================================ */

.section {
  position: relative;
  padding: 96px 0;
}

.section--void { background: var(--c-void); }
.section--slate { background: var(--c-slate); }
.section--violet {
  background: var(--c-violet);
  color: var(--c-coldframe);
  position: relative;
  overflow: hidden;
}

.section-head {
  margin-bottom: 56px;
  max-width: 720px;
}

.section-head .eyebrow {
  margin-bottom: 12px;
}

.section-head .h-2 {
  margin-top: 4px;
}

.section-head--center {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

/* ============================================================
   Feature grid (home, accommodations s3 — different treatment)
   ============================================================ */

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.feature-card {
  background: var(--c-card);
  border: 1.5px solid var(--c-graphite);
  border-top: 2px solid var(--c-cyan);
  padding: 36px;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: all 250ms var(--ease);
  min-height: 320px;
}

.feature-card:hover {
  border-color: var(--c-cyan);
  border-top-color: var(--c-cyan);
  box-shadow: 0 0 24px rgba(0, 212, 232, 0.18);
  transform: translateY(-2px);
}

.feature-card:hover .feature-title {
  color: var(--c-cyan);
}

.feature-icon {
  width: 32px;
  height: 32px;
  color: var(--c-cyan);
  margin-bottom: 16px;
}

.feature-icon svg {
  width: 100%;
  height: 100%;
}

.feature-card-rule {
  width: 100%;
  height: 1px;
  background: var(--c-graphite);
  margin-bottom: 16px;
}

.feature-title {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 24px;
  color: var(--c-coldframe);
  letter-spacing: -0.005em;
  margin-bottom: 12px;
  transition: color 200ms var(--ease);
}

.feature-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
}

.feature-tag {
  margin-top: auto;
  padding-top: 24px;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

@media (max-width: 1024px) {
  .feature-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .feature-grid { grid-template-columns: 1fr; gap: 24px; }
}

/* ============================================================
   CTA section (home s3, journal s3)
   ============================================================ */

.cta-section {
  background: var(--c-violet);
  text-align: center;
  position: relative;
  overflow: hidden;
  padding: 104px 0;
}

.cta-section .eyebrow {
  margin-bottom: 16px;
}

.cta-section .h-1 {
  max-width: 720px;
  margin: 0 auto 20px;
}

.cta-section .subhead {
  margin: 0 auto;
  text-align: center;
  max-width: 540px;
  color: rgba(237, 241, 247, 0.85);
}

.cta-section .btn-row {
  margin-top: 44px;
  justify-content: center;
}

.cta-pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.08;
  z-index: 0;
}

.cta-pattern svg { width: 100%; height: 100%; }

.cta-section .container {
  position: relative;
  z-index: 1;
}

.cta-section .rule-divider {
  background: rgba(46, 58, 80, 0.4);
}
.cta-section .rule-divider::after {
  background: var(--c-amethyst);
  box-shadow: 0 0 8px rgba(192, 132, 252, 0.6);
}

/* ============================================================
   Page header (used in accommodations, offers, journal, contact)
   ============================================================ */

.page-header {
  background: var(--c-void);
  padding: 128px 0 96px;
  position: relative;
  overflow: hidden;
}

.page-header-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.page-header .eyebrow {
  margin-bottom: 24px;
}

.page-header .h-display {
  margin-bottom: 28px;
}

.page-header-pattern {
  position: absolute;
  top: 0;
  right: 0;
  width: 55%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.45;
}

.page-header-pattern svg { width: 100%; height: 100%; }

.page-header-divider {
  margin-top: 56px;
  height: 1px;
  background: var(--c-graphite);
  position: relative;
  z-index: 1;
}

@media (max-width: 768px) {
  .page-header { padding: 80px 0 64px; }
  .page-header-pattern { opacity: 0.18; width: 100%; }
}

/* ============================================================
   Item grid — Accommodations s2 (signature)
   ============================================================ */

.room-grid-section {
  background: linear-gradient(135deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.room-grid-pattern {
  position: absolute;
  top: 0;
  right: 0;
  width: 60%;
  height: 60%;
  opacity: 0.07;
  pointer-events: none;
}

.room-grid-section .eyebrow {
  color: rgba(237, 241, 247, 0.7);
}

.room-grid-section .h-2 {
  color: var(--c-coldframe);
  max-width: 640px;
}

.room-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  position: relative;
  z-index: 1;
}

.room-card {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  border-radius: 16px;
  padding: 32px 28px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: all 250ms var(--ease);
  position: relative;
}

.room-card:hover {
  border-color: var(--c-cyan);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4),
              0 0 24px rgba(0, 212, 232, 0.2);
  transform: translateY(-2px);
}

.room-id {
  font-family: var(--f-mono);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
  display: block;
}

.room-card-rule {
  height: 1px;
  width: 100%;
  background: var(--c-graphite);
  margin-bottom: 14px;
}

.room-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-coldframe);
  margin-bottom: 20px;
}

.room-meta {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 6px 16px;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.10em;
  color: var(--c-mist);
}

.room-meta dt {
  text-transform: uppercase;
  color: var(--c-mist);
}

.room-meta dd {
  color: var(--c-coldframe);
}

.room-grid-cta {
  margin-top: 48px;
  display: flex;
  justify-content: center;
}

@media (max-width: 768px) {
  .room-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   Index strip — Accommodations s3
   ============================================================ */

.index-strip {
  display: grid;
  grid-template-columns: 3fr 9fr;
  position: relative;
}

.index-strip::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(3 / 12 * 100%);
  width: 1px;
  background: var(--c-graphite);
}

.index-row {
  display: contents;
}

.index-cell {
  padding: 40px 32px 40px 0;
  border-top: 1px solid var(--c-graphite);
}

.index-row:first-child .index-cell {
  border-top: none;
  padding-top: 0;
}

.index-row:last-child .index-cell {
  padding-bottom: 0;
}

.index-label {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-mist);
}

.index-cell--right {
  padding-left: 32px;
}

.index-title {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: 28px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}

.index-desc {
  font-size: 17px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 520px;
}

@media (max-width: 768px) {
  .index-strip { grid-template-columns: 1fr; }
  .index-strip::before { display: none; }
  .index-cell { padding: 28px 0; border-top: 1px solid var(--c-graphite); }
  .index-cell--right { padding-left: 0; padding-top: 0; }
  .index-cell--label { padding-bottom: 12px; }
  .index-row:first-child .index-cell--right { border-top: none; }
}

/* ============================================================
   Pricing — Offers s2
   ============================================================ */

.pricing-section {
  background: var(--c-slate);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.pricing-ghost {
  position: absolute;
  top: 50%;
  left: 35%;
  transform: translateY(-50%);
  font-family: var(--f-mono);
  font-weight: 200;
  font-size: clamp(120px, 18vw, 220px);
  color: var(--c-violet);
  opacity: 0.07;
  white-space: nowrap;
  letter-spacing: -0.02em;
  pointer-events: none;
  z-index: 0;
  user-select: none;
}

.pricing-grid {
  display: grid;
  grid-template-columns: 3fr 5fr 3fr;
  gap: 24px;
  position: relative;
  z-index: 1;
  align-items: stretch;
}

.price-card {
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  border-radius: 4px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: all 250ms var(--ease);
}

.price-card:hover {
  border-color: var(--c-cyan);
  box-shadow: 0 0 0 1.5px var(--c-cyan), 0 0 28px rgba(0, 212, 232, 0.15);
}

.price-card--featured {
  padding: 36px 32px;
  margin-top: -20px;
  border-left: 3px solid var(--c-violet);
}

.price-most-popular {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-violet);
  margin-bottom: 10px;
}

.price-rate {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
}

.price-title {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 28px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}

.price-card--featured .price-title {
  font-size: 32px;
}

.price-bestfor-rule {
  height: 1px;
  background: var(--c-graphite);
  margin: 14px 0 10px;
}

.price-bestfor {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--c-mist);
  margin-bottom: 16px;
}

.price-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  margin-bottom: 24px;
  flex-grow: 1;
}

.price-card--featured .price-desc {
  color: var(--c-coldframe);
}

.price-foot-rule {
  height: 1px;
  background: var(--c-graphite);
  margin-bottom: 16px;
}

.price-link {
  font-family: var(--f-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--c-violet);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  transition: color 200ms var(--ease);
}

.price-link::after {
  content: "→";
  transition: transform 200ms var(--ease);
}

.price-link:hover::after {
  transform: translateX(4px);
}

.price-link--cyan {
  color: var(--c-cyan);
}

.price-corner {
  position: absolute;
  bottom: 16px;
  right: 16px;
  width: 36px;
  height: 12px;
  opacity: 0.3;
}

.pricing-cta-row {
  margin-top: 56px;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  position: relative;
  z-index: 1;
}

@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: 1fr; }
  .price-card--featured { margin-top: 0; }
}

/* ============================================================
   Article list — Journal s2
   ============================================================ */

.article-list-section {
  background: var(--c-slate);
  padding: 80px 0 100px;
  position: relative;
}

.article-list {
  border-top: 1px solid var(--c-graphite);
}

.article-row {
  display: grid;
  grid-template-columns: 3fr 9fr;
  gap: 32px;
  padding: 40px 0;
  border-bottom: 1px solid var(--c-graphite);
  align-items: center;
  position: relative;
  cursor: pointer;
  transition: background 200ms var(--ease);
}

.article-row:hover {
  background: rgba(0, 212, 232, 0.02);
}

.article-row:hover .article-title {
  color: var(--c-violet);
}

.article-row:hover .article-arrow {
  transform: translateX(6px);
  color: var(--c-amethyst);
}

.article-meta {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.article-chip {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  padding: 4px 10px;
  border: 1px solid var(--c-cyan);
  border-radius: 2px;
}

.article-readtime {
  font-family: var(--f-mono);
  font-size: 11px;
  color: var(--c-mist);
  letter-spacing: 0.05em;
}

.article-content {
  display: flex;
  align-items: center;
  gap: 24px;
  justify-content: space-between;
}

.article-text {
  flex: 1;
}

.article-title {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: 24px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 10px;
  transition: color 200ms var(--ease);
}

.article-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 600px;
}

.article-arrow {
  font-family: var(--f-mono);
  font-size: 18px;
  color: var(--c-cyan);
  flex-shrink: 0;
  transition: transform 200ms var(--ease), color 200ms var(--ease);
}

@media (max-width: 768px) {
  .article-row { grid-template-columns: 1fr; gap: 16px; padding: 32px 0; }
  .article-meta { flex-direction: row; align-items: center; gap: 16px; }
  .article-content { flex-direction: column; align-items: flex-start; }
  .article-arrow { align-self: flex-end; }
}

/* ============================================================
   Contact block — Contact s2 (signature: terminal form)
   ============================================================ */

.contact-section {
  background: var(--c-slate);
  padding: 80px 0 96px;
}

.contact-grid {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 48px;
  align-items: start;
}

.channel-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.channel-card {
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  padding: 20px;
  position: relative;
}

.channel-card:first-child {
  border-top: 1px solid var(--c-cyan);
  box-shadow: 0 -1px 0 var(--c-cyan);
}

.channel-title {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
}

.channel-desc {
  font-size: 14px;
  line-height: 1.55;
  color: var(--c-mist);
  margin-bottom: 14px;
}

.channel-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--f-mono);
  font-size: 13px;
  color: var(--c-coldframe);
}

.channel-row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  flex-wrap: wrap;
}

.channel-key {
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  flex-shrink: 0;
}

.channel-value {
  color: var(--c-coldframe);
  word-break: break-all;
}

/* Form terminal */

.form-terminal {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  border-top: 2px solid var(--c-cyan);
  padding: 40px;
  box-shadow: 0 8px 40px rgba(0, 212, 232, 0.08);
  position: relative;
}

.form-fields {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field--row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 600px) {
  .field--row { grid-template-columns: 1fr; }
}

.field label {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  color: var(--c-coldframe);
  font-family: var(--f-body);
  font-size: 15px;
  padding: 12px 16px;
  outline: none;
  transition: all 200ms var(--ease);
  border-radius: 0;
}

.field input::placeholder,
.field textarea::placeholder {
  color: var(--c-mist);
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--c-violet);
  box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.25);
}

.field textarea {
  resize: vertical;
  min-height: 120px;
  line-height: 1.55;
  font-family: var(--f-body);
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--c-cyan) 50%),
                    linear-gradient(135deg, var(--c-cyan) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 12px) 50%;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  padding-right: 40px;
}

.form-submit {
  margin-top: 28px;
  width: 100%;
  background: linear-gradient(90deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  color: var(--c-coldframe);
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 16px 24px;
  border: none;
  cursor: pointer;
  transition: all 250ms var(--ease);
  background-size: 200% 100%;
  background-position: 0% 0%;
}

.form-submit:hover {
  background-position: 100% 0%;
  box-shadow: 0 0 24px rgba(0, 212, 232, 0.35);
}

.form-caption {
  margin-top: 14px;
  font-family: var(--f-mono);
  font-size: 10px;
  color: var(--c-mist);
  letter-spacing: 0.05em;
}

@media (max-width: 900px) {
  .contact-grid { grid-template-columns: 1fr; gap: 32px; }
}

/* ============================================================
   Map block — Contact s3
   ============================================================ */

.map-section {
  background: var(--c-void);
  padding-top: 0;
  padding-bottom: 80px;
}

.map-band {
  width: 100%;
  height: 420px;
  position: relative;
  background: var(--c-slate);
  overflow: hidden;
  margin-bottom: 56px;
}

.map-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.map-svg svg {
  width: 100%;
  height: 100%;
}

.map-overlay {
  position: absolute;
  inset: 0;
  background: rgba(30, 37, 53, 0.45);
  pointer-events: none;
}

.map-pin {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  gap: 16px;
  z-index: 2;
}

.pin-marker {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--c-violet);
  position: relative;
  box-shadow: 0 0 8px rgba(124, 58, 237, 0.8);
  flex-shrink: 0;
}

.pin-marker::before,
.pin-marker::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1.5px solid var(--c-cyan);
  animation: pulse-ring 2.4s ease-out infinite;
  pointer-events: none;
}

.pin-marker::after {
  animation-delay: 1.2s;
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 0.8;
  }
  100% {
    transform: scale(4.2);
    opacity: 0;
  }
}

.pin-label {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  padding: 12px 16px;
  position: relative;
  z-index: 2;
}

.pin-label-id {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: block;
  margin-bottom: 4px;
}

.pin-label-addr {
  font-size: 13px;
  color: var(--c-coldframe);
  font-family: var(--f-body);
}

@media (max-width: 768px) {
  .map-band { height: 240px; }
  .pin-label { display: none; }
}

.location-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
}

.location-cell {
  padding: 0 32px;
  border-left: 1px solid var(--c-graphite);
}

.location-cell:first-child {
  padding-left: 0;
  border-left: none;
}

.location-label {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: block;
  margin-bottom: 12px;
}

.location-text {
  font-size: 15px;
  line-height: 1.6;
  color: var(--c-coldframe);
}

@media (max-width: 768px) {
  .location-grid { grid-template-columns: 1fr; gap: 32px; }
  .location-cell { padding: 0; border-left: none; }
}

/* ============================================================
   Footer
   ============================================================ */

.site-footer {
  background: var(--c-void);
  border-top: 1px solid var(--c-graphite);
  padding: 56px 0 32px;
  color: var(--c-mist);
  font-size: 14px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.footer-brand .brand {
  font-size: 20px;
}

.footer-tagline {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

.footer-blurb {
  color: var(--c-mist);
  font-size: 14px;
  line-height: 1.6;
  max-width: 320px;
}

.footer-col h4 {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 16px;
  font-weight: 400;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--c-coldframe);
  font-size: 14px;
  transition: color 200ms var(--ease);
}

.footer-col a:hover { color: var(--c-cyan); }

.footer-bottom {
  border-top: 1px solid var(--c-graphite);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-mist);
  flex-wrap: wrap;
  gap: 16px;
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   Misc helpers
   ============================================================ */

.section-rule {
  height: 1px;
  background: var(--c-graphite);
  position: relative;
}

.section-rule::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-cyan);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

.urgency-tag {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(237, 241, 247, 0.6);
  margin-bottom: 16px;
}

.cta-asym {
  background: var(--c-violet);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.cta-asym-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 48px;
  position: relative;
  z-index: 1;
  align-items: center;
}

.cta-asym-pattern {
  position: absolute;
  top: 0;
  right: -10%;
  width: 70%;
  height: 100%;
  opacity: 0.18;
  pointer-events: none;
  z-index: 0;
}

.cta-asym-pattern svg { width: 100%; height: 100%; }

.cta-asym .h-1 { color: var(--c-coldframe); }
.cta-asym .subhead {
  color: rgba(237, 241, 247, 0.85);
  margin-top: 20px;
  max-width: 560px;
}

.cta-asym .btn-row { margin-top: 40px; justify-content: flex-start; }

@media (max-width: 900px) {
  .cta-asym-grid { grid-template-columns: 1fr; }
  .cta-asym-pattern { width: 100%; opacity: 0.1; }
}

/* Page-level scoped tweaks via data-page-slug */

body[data-page-slug="home"] .hero-headline { letter-spacing: -0.03em; }

tool_use_result.content:
/* ============================================================
   AXIOM HOTEL — Design System
   ============================================================ */

:root {
  --c-void: #0A0C14;
  --c-coldframe: #EDF1F7;
  --c-violet: #7C3AED;
  --c-cyan: #00D4E8;
  --c-slate: #1E2535;
  --c-mist: #8B9BB8;
  --c-amethyst: #C084FC;
  --c-graphite: #2E3A50;

  --c-card: #222A3A;

  --f-heading: 'Archivo', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-body: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Consolas, monospace;

  --grid-max: 1280px;
  --grid-pad: 80px;

  --ease: cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--f-body);
  background: var(--c-void);
  color: var(--c-coldframe);
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
  color: inherit;
}

img, svg {
  display: block;
  max-width: 100%;
}

ul {
  list-style: none;
}

/* ============================================================
   Layout primitives
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--grid-max);
  margin: 0 auto;
  padding: 0 var(--grid-pad);
}

@media (max-width: 1024px) {
  :root { --grid-pad: 48px; }
}
@media (max-width: 768px) {
  :root { --grid-pad: 24px; }
}

/* Transition rule: thin Signal Graphite line with cyan node-dot */
.rule-divider {
  position: relative;
  width: 100%;
  height: 1px;
  background: var(--c-graphite);
}
.rule-divider::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-cyan);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

/* ============================================================
   Top navigation bar
   ============================================================ */

.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 12, 20, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--c-graphite);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: 18px;
  letter-spacing: -0.02em;
  color: var(--c-coldframe);
  text-transform: uppercase;
}

.brand-mark {
  width: 28px;
  height: 28px;
}

.brand-tag {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  color: var(--c-cyan);
  text-transform: uppercase;
  margin-left: 4px;
  padding-left: 12px;
  border-left: 1px solid var(--c-graphite);
}

.nav-links {
  display: flex;
  gap: 36px;
  align-items: center;
}

.nav-links a {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-mist);
  position: relative;
  padding: 8px 0;
  transition: color 200ms var(--ease);
}

.nav-links a:hover {
  color: var(--c-coldframe);
}

.nav-links a.active {
  color: var(--c-cyan);
}

.nav-links a.active::after {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 0;
  width: 100%;
  height: 1px;
  background: var(--c-cyan);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

.nav-cta {
  font-family: var(--f-body);
  font-weight: 600;
  font-size: 14px;
  background: var(--c-violet);
  color: var(--c-coldframe);
  padding: 10px 22px;
  transition: background 200ms var(--ease);
}

.nav-cta:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
}

.nav-toggle {
  display: none;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

@media (max-width: 900px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .nav-toggle { display: inline-block; }
}

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--f-body);
  font-weight: 600;
  font-size: 15px;
  padding: 14px 32px;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: all 200ms var(--ease);
  text-transform: none;
  letter-spacing: 0;
}

.btn--primary {
  background: var(--c-violet);
  color: var(--c-coldframe);
}

.btn--primary:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
  box-shadow: 0 0 24px rgba(192, 132, 252, 0.35);
}

.btn--ghost {
  background: transparent;
  border-color: var(--c-graphite);
  color: var(--c-coldframe);
}

.btn--ghost:hover {
  border-color: var(--c-cyan);
  color: var(--c-cyan);
  box-shadow: 0 0 12px rgba(0, 212, 232, 0.35);
}

.btn--invert {
  background: var(--c-coldframe);
  color: var(--c-void);
}

.btn--invert:hover {
  background: var(--c-amethyst);
  color: var(--c-void);
}

.btn--ghost-light {
  background: transparent;
  border-color: var(--c-coldframe);
  color: var(--c-coldframe);
}

.btn--ghost-light:hover {
  background: rgba(237, 241, 247, 0.1);
  border-color: var(--c-amethyst);
  color: var(--c-amethyst);
}

.btn--inverse {
  background: var(--c-void);
  color: var(--c-coldframe);
}

.btn--inverse:hover {
  background: var(--c-graphite);
  border-color: var(--c-coldframe);
}

.btn--block {
  width: 100%;
}

.btn-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 40px;
}

.btn-row--center {
  justify-content: center;
}

@media (max-width: 600px) {
  .btn-row { flex-direction: column; }
  .btn { width: 100%; }
}

/* ============================================================
   Eyebrow + headline patterns
   ============================================================ */

.eyebrow {
  font-family: var(--f-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: inline-block;
}

.eyebrow--rule::after {
  content: "";
  display: block;
  width: 28px;
  height: 2px;
  background: var(--c-cyan);
  margin-top: 8px;
  box-shadow: 0 0 6px rgba(0, 212, 232, 0.6);
}

.eyebrow--mist {
  color: var(--c-mist);
}

.eyebrow--amethyst {
  color: var(--c-amethyst);
}
.eyebrow--amethyst.eyebrow--rule::after {
  background: var(--c-amethyst);
  width: 32px;
  box-shadow: 0 0 6px rgba(192, 132, 252, 0.6);
}

.eyebrow--white {
  color: rgba(237, 241, 247, 0.8);
}
.eyebrow--white.eyebrow--rule::after {
  background: var(--c-coldframe);
  width: 32px;
  box-shadow: 0 0 6px rgba(237, 241, 247, 0.4);
}

.h-display {
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: clamp(40px, 6.5vw, 76px);
  line-height: 1.05;
  letter-spacing: -0.03em;
  color: var(--c-coldframe);
}

.h-1 {
  font-family: var(--f-heading);
  font-weight: 900;
  font-size: clamp(36px, 5.5vw, 64px);
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--c-coldframe);
}

.h-2 {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: clamp(32px, 4vw, 44px);
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--c-coldframe);
}

.h-3 {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: clamp(22px, 2.4vw, 28px);
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--c-coldframe);
}

.text-grad {
  background: linear-gradient(90deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

.subhead {
  font-family: var(--f-body);
  font-size: 18px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 560px;
}

.subhead--white {
  color: rgba(237, 241, 247, 0.85);
}

.lead-body {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 600px;
}

/* ============================================================
   Hero — Home
   ============================================================ */

.hero {
  position: relative;
  min-height: 100vh;
  background: var(--c-void);
  overflow: hidden;
  display: flex;
  align-items: center;
  padding: 160px 0 140px;
  isolation: isolate;
}

.hero-pattern {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.hero-pattern svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-pattern::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 80% at 0% 50%,
    rgba(10, 12, 20, 0.92) 0%,
    rgba(10, 12, 20, 0.6) 40%,
    rgba(10, 12, 20, 0) 80%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.hero .eyebrow {
  margin-bottom: 24px;
}

.hero-headline {
  margin-top: 0;
}

.hero-sub {
  margin-top: 24px;
  max-width: 520px;
}

@media (max-width: 768px) {
  .hero { padding: 96px 0 80px; min-height: auto; }
  .hero-pattern { opacity: 0.45; }
}

/* ============================================================
   Section base + alternation
   ============================================================ */

.section {
  position: relative;
  padding: 96px 0;
}

.section--void { background: var(--c-void); }
.section--slate { background: var(--c-slate); }
.section--violet {
  background: var(--c-violet);
  color: var(--c-coldframe);
  position: relative;
  overflow: hidden;
}

.section-head {
  margin-bottom: 56px;
  max-width: 720px;
}

.section-head .eyebrow {
  margin-bottom: 12px;
}

.section-head .h-2 {
  margin-top: 4px;
}

.section-head--center {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

/* ============================================================
   Feature grid (home, accommodations s3 — different treatment)
   ============================================================ */

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.feature-card {
  background: var(--c-card);
  border: 1.5px solid var(--c-graphite);
  border-top: 2px solid var(--c-cyan);
  padding: 36px;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: all 250ms var(--ease);
  min-height: 320px;
}

.feature-card:hover {
  border-color: var(--c-cyan);
  border-top-color: var(--c-cyan);
  box-shadow: 0 0 24px rgba(0, 212, 232, 0.18);
  transform: translateY(-2px);
}

.feature-card:hover .feature-title {
  color: var(--c-cyan);
}

.feature-icon {
  width: 32px;
  height: 32px;
  color: var(--c-cyan);
  margin-bottom: 16px;
}

.feature-icon svg {
  width: 100%;
  height: 100%;
}

.feature-card-rule {
  width: 100%;
  height: 1px;
  background: var(--c-graphite);
  margin-bottom: 16px;
}

.feature-title {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 24px;
  color: var(--c-coldframe);
  letter-spacing: -0.005em;
  margin-bottom: 12px;
  transition: color 200ms var(--ease);
}

.feature-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
}

.feature-tag {
  margin-top: auto;
  padding-top: 24px;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

@media (max-width: 1024px) {
  .feature-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .feature-grid { grid-template-columns: 1fr; gap: 24px; }
}

/* ============================================================
   CTA section (home s3, journal s3)
   ============================================================ */

.cta-section {
  background: var(--c-violet);
  text-align: center;
  position: relative;
  overflow: hidden;
  padding: 104px 0;
}

.cta-section .eyebrow {
  margin-bottom: 16px;
}

.cta-section .h-1 {
  max-width: 720px;
  margin: 0 auto 20px;
}

.cta-section .subhead {
  margin: 0 auto;
  text-align: center;
  max-width: 540px;
  color: rgba(237, 241, 247, 0.85);
}

.cta-section .btn-row {
  margin-top: 44px;
  justify-content: center;
}

.cta-pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.08;
  z-index: 0;
}

.cta-pattern svg { width: 100%; height: 100%; }

.cta-section .container {
  position: relative;
  z-index: 1;
}

.cta-section .rule-divider {
  background: rgba(46, 58, 80, 0.4);
}
.cta-section .rule-divider::after {
  background: var(--c-amethyst);
  box-shadow: 0 0 8px rgba(192, 132, 252, 0.6);
}

/* ============================================================
   Page header (used in accommodations, offers, journal, contact)
   ============================================================ */

.page-header {
  background: var(--c-void);
  padding: 128px 0 96px;
  position: relative;
  overflow: hidden;
}

.page-header-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.page-header .eyebrow {
  margin-bottom: 24px;
}

.page-header .h-display {
  margin-bottom: 28px;
}

.page-header-pattern {
  position: absolute;
  top: 0;
  right: 0;
  width: 55%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.45;
}

.page-header-pattern svg { width: 100%; height: 100%; }

.page-header-divider {
  margin-top: 56px;
  height: 1px;
  background: var(--c-graphite);
  position: relative;
  z-index: 1;
}

@media (max-width: 768px) {
  .page-header { padding: 80px 0 64px; }
  .page-header-pattern { opacity: 0.18; width: 100%; }
}

/* ============================================================
   Item grid — Accommodations s2 (signature)
   ============================================================ */

.room-grid-section {
  background: linear-gradient(135deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.room-grid-pattern {
  position: absolute;
  top: 0;
  right: 0;
  width: 60%;
  height: 60%;
  opacity: 0.07;
  pointer-events: none;
}

.room-grid-section .eyebrow {
  color: rgba(237, 241, 247, 0.7);
}

.room-grid-section .h-2 {
  color: var(--c-coldframe);
  max-width: 640px;
}

.room-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  position: relative;
  z-index: 1;
}

.room-card {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  border-radius: 16px;
  padding: 32px 28px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: all 250ms var(--ease);
  position: relative;
}

.room-card:hover {
  border-color: var(--c-cyan);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4),
              0 0 24px rgba(0, 212, 232, 0.2);
  transform: translateY(-2px);
}

.room-id {
  font-family: var(--f-mono);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
  display: block;
}

.room-card-rule {
  height: 1px;
  width: 100%;
  background: var(--c-graphite);
  margin-bottom: 14px;
}

.room-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-coldframe);
  margin-bottom: 20px;
}

.room-meta {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 6px 16px;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.10em;
  color: var(--c-mist);
}

.room-meta dt {
  text-transform: uppercase;
  color: var(--c-mist);
}

.room-meta dd {
  color: var(--c-coldframe);
}

.room-grid-cta {
  margin-top: 48px;
  display: flex;
  justify-content: center;
}

@media (max-width: 768px) {
  .room-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   Index strip — Accommodations s3
   ============================================================ */

.index-strip {
  display: grid;
  grid-template-columns: 3fr 9fr;
  position: relative;
}

.index-strip::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(3 / 12 * 100%);
  width: 1px;
  background: var(--c-graphite);
}

.index-row {
  display: contents;
}

.index-cell {
  padding: 40px 32px 40px 0;
  border-top: 1px solid var(--c-graphite);
}

.index-row:first-child .index-cell {
  border-top: none;
  padding-top: 0;
}

.index-row:last-child .index-cell {
  padding-bottom: 0;
}

.index-label {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-mist);
}

.index-cell--right {
  padding-left: 32px;
}

.index-title {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: 28px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}

.index-desc {
  font-size: 17px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 520px;
}

@media (max-width: 768px) {
  .index-strip { grid-template-columns: 1fr; }
  .index-strip::before { display: none; }
  .index-cell { padding: 28px 0; border-top: 1px solid var(--c-graphite); }
  .index-cell--right { padding-left: 0; padding-top: 0; }
  .index-cell--label { padding-bottom: 12px; }
  .index-row:first-child .index-cell--right { border-top: none; }
}

/* ============================================================
   Pricing — Offers s2
   ============================================================ */

.pricing-section {
  background: var(--c-slate);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.pricing-ghost {
  position: absolute;
  top: 50%;
  left: 35%;
  transform: translateY(-50%);
  font-family: var(--f-mono);
  font-weight: 200;
  font-size: clamp(120px, 18vw, 220px);
  color: var(--c-violet);
  opacity: 0.07;
  white-space: nowrap;
  letter-spacing: -0.02em;
  pointer-events: none;
  z-index: 0;
  user-select: none;
}

.pricing-grid {
  display: grid;
  grid-template-columns: 3fr 5fr 3fr;
  gap: 24px;
  position: relative;
  z-index: 1;
  align-items: stretch;
}

.price-card {
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  border-radius: 4px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: all 250ms var(--ease);
}

.price-card:hover {
  border-color: var(--c-cyan);
  box-shadow: 0 0 0 1.5px var(--c-cyan), 0 0 28px rgba(0, 212, 232, 0.15);
}

.price-card--featured {
  padding: 36px 32px;
  margin-top: -20px;
  border-left: 3px solid var(--c-violet);
}

.price-most-popular {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-violet);
  margin-bottom: 10px;
}

.price-rate {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
}

.price-title {
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 28px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}

.price-card--featured .price-title {
  font-size: 32px;
}

.price-bestfor-rule {
  height: 1px;
  background: var(--c-graphite);
  margin: 14px 0 10px;
}

.price-bestfor {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--c-mist);
  margin-bottom: 16px;
}

.price-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  margin-bottom: 24px;
  flex-grow: 1;
}

.price-card--featured .price-desc {
  color: var(--c-coldframe);
}

.price-foot-rule {
  height: 1px;
  background: var(--c-graphite);
  margin-bottom: 16px;
}

.price-link {
  font-family: var(--f-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--c-violet);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  transition: color 200ms var(--ease);
}

.price-link::after {
  content: "→";
  transition: transform 200ms var(--ease);
}

.price-link:hover::after {
  transform: translateX(4px);
}

.price-link--cyan {
  color: var(--c-cyan);
}

.price-corner {
  position: absolute;
  bottom: 16px;
  right: 16px;
  width: 36px;
  height: 12px;
  opacity: 0.3;
}

.pricing-cta-row {
  margin-top: 56px;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  position: relative;
  z-index: 1;
}

@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: 1fr; }
  .price-card--featured { margin-top: 0; }
}

/* ============================================================
   Article list — Journal s2
   ============================================================ */

.article-list-section {
  background: var(--c-slate);
  padding: 80px 0 100px;
  position: relative;
}

.article-list {
  border-top: 1px solid var(--c-graphite);
}

.article-row {
  display: grid;
  grid-template-columns: 3fr 9fr;
  gap: 32px;
  padding: 40px 0;
  border-bottom: 1px solid var(--c-graphite);
  align-items: center;
  position: relative;
  cursor: pointer;
  transition: background 200ms var(--ease);
}

.article-row:hover {
  background: rgba(0, 212, 232, 0.02);
}

.article-row:hover .article-title {
  color: var(--c-violet);
}

.article-row:hover .article-arrow {
  transform: translateX(6px);
  color: var(--c-amethyst);
}

.article-meta {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.article-chip {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  padding: 4px 10px;
  border: 1px solid var(--c-cyan);
  border-radius: 2px;
}

.article-readtime {
  font-family: var(--f-mono);
  font-size: 11px;
  color: var(--c-mist);
  letter-spacing: 0.05em;
}

.article-content {
  display: flex;
  align-items: center;
  gap: 24px;
  justify-content: space-between;
}

.article-text {
  flex: 1;
}

.article-title {
  font-family: var(--f-heading);
  font-weight: 600;
  font-size: 24px;
  color: var(--c-coldframe);
  letter-spacing: -0.01em;
  margin-bottom: 10px;
  transition: color 200ms var(--ease);
}

.article-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--c-mist);
  max-width: 600px;
}

.article-arrow {
  font-family: var(--f-mono);
  font-size: 18px;
  color: var(--c-cyan);
  flex-shrink: 0;
  transition: transform 200ms var(--ease), color 200ms var(--ease);
}

@media (max-width: 768px) {
  .article-row { grid-template-columns: 1fr; gap: 16px; padding: 32px 0; }
  .article-meta { flex-direction: row; align-items: center; gap: 16px; }
  .article-content { flex-direction: column; align-items: flex-start; }
  .article-arrow { align-self: flex-end; }
}

/* ============================================================
   Contact block — Contact s2 (signature: terminal form)
   ============================================================ */

.contact-section {
  background: var(--c-slate);
  padding: 80px 0 96px;
}

.contact-grid {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 48px;
  align-items: start;
}

.channel-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.channel-card {
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  padding: 20px;
  position: relative;
}

.channel-card:first-child {
  border-top: 1px solid var(--c-cyan);
  box-shadow: 0 -1px 0 var(--c-cyan);
}

.channel-title {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 12px;
}

.channel-desc {
  font-size: 14px;
  line-height: 1.55;
  color: var(--c-mist);
  margin-bottom: 14px;
}

.channel-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--f-mono);
  font-size: 13px;
  color: var(--c-coldframe);
}

.channel-row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  flex-wrap: wrap;
}

.channel-key {
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  flex-shrink: 0;
}

.channel-value {
  color: var(--c-coldframe);
  word-break: break-all;
}

/* Form terminal */

.form-terminal {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  border-top: 2px solid var(--c-cyan);
  padding: 40px;
  box-shadow: 0 8px 40px rgba(0, 212, 232, 0.08);
  position: relative;
}

.form-fields {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field--row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 600px) {
  .field--row { grid-template-columns: 1fr; }
}

.field label {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  background: var(--c-void);
  border: 1px solid var(--c-graphite);
  color: var(--c-coldframe);
  font-family: var(--f-body);
  font-size: 15px;
  padding: 12px 16px;
  outline: none;
  transition: all 200ms var(--ease);
  border-radius: 0;
}

.field input::placeholder,
.field textarea::placeholder {
  color: var(--c-mist);
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--c-violet);
  box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.25);
}

.field textarea {
  resize: vertical;
  min-height: 120px;
  line-height: 1.55;
  font-family: var(--f-body);
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--c-cyan) 50%),
                    linear-gradient(135deg, var(--c-cyan) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 12px) 50%;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  padding-right: 40px;
}

.form-submit {
  margin-top: 28px;
  width: 100%;
  background: linear-gradient(90deg, var(--c-violet) 0%, var(--c-amethyst) 100%);
  color: var(--c-coldframe);
  font-family: var(--f-heading);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 16px 24px;
  border: none;
  cursor: pointer;
  transition: all 250ms var(--ease);
  background-size: 200% 100%;
  background-position: 0% 0%;
}

.form-submit:hover {
  background-position: 100% 0%;
  box-shadow: 0 0 24px rgba(0, 212, 232, 0.35);
}

.form-caption {
  margin-top: 14px;
  font-family: var(--f-mono);
  font-size: 10px;
  color: var(--c-mist);
  letter-spacing: 0.05em;
}

@media (max-width: 900px) {
  .contact-grid { grid-template-columns: 1fr; gap: 32px; }
}

/* ============================================================
   Map block — Contact s3
   ============================================================ */

.map-section {
  background: var(--c-void);
  padding-top: 0;
  padding-bottom: 80px;
}

.map-band {
  width: 100%;
  height: 420px;
  position: relative;
  background: var(--c-slate);
  overflow: hidden;
  margin-bottom: 56px;
}

.map-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.map-svg svg {
  width: 100%;
  height: 100%;
}

.map-overlay {
  position: absolute;
  inset: 0;
  background: rgba(30, 37, 53, 0.45);
  pointer-events: none;
}

.map-pin {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  gap: 16px;
  z-index: 2;
}

.pin-marker {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--c-violet);
  position: relative;
  box-shadow: 0 0 8px rgba(124, 58, 237, 0.8);
  flex-shrink: 0;
}

.pin-marker::before,
.pin-marker::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1.5px solid var(--c-cyan);
  animation: pulse-ring 2.4s ease-out infinite;
  pointer-events: none;
}

.pin-marker::after {
  animation-delay: 1.2s;
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 0.8;
  }
  100% {
    transform: scale(4.2);
    opacity: 0;
  }
}

.pin-label {
  background: var(--c-slate);
  border: 1px solid var(--c-graphite);
  padding: 12px 16px;
  position: relative;
  z-index: 2;
}

.pin-label-id {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: block;
  margin-bottom: 4px;
}

.pin-label-addr {
  font-size: 13px;
  color: var(--c-coldframe);
  font-family: var(--f-body);
}

@media (max-width: 768px) {
  .map-band { height: 240px; }
  .pin-label { display: none; }
}

.location-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
}

.location-cell {
  padding: 0 32px;
  border-left: 1px solid var(--c-graphite);
}

.location-cell:first-child {
  padding-left: 0;
  border-left: none;
}

.location-label {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--c-cyan);
  display: block;
  margin-bottom: 12px;
}

.location-text {
  font-size: 15px;
  line-height: 1.6;
  color: var(--c-coldframe);
}

@media (max-width: 768px) {
  .location-grid { grid-template-columns: 1fr; gap: 32px; }
  .location-cell { padding: 0; border-left: none; }
}

/* ============================================================
   Footer
   ============================================================ */

.site-footer {
  background: var(--c-void);
  border-top: 1px solid var(--c-graphite);
  padding: 56px 0 32px;
  color: var(--c-mist);
  font-size: 14px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.footer-brand .brand {
  font-size: 20px;
}

.footer-tagline {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
}

.footer-blurb {
  color: var(--c-mist);
  font-size: 14px;
  line-height: 1.6;
  max-width: 320px;
}

.footer-col h4 {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-cyan);
  margin-bottom: 16px;
  font-weight: 400;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--c-coldframe);
  font-size: 14px;
  transition: color 200ms var(--ease);
}

.footer-col a:hover { color: var(--c-cyan); }

.footer-bottom {
  border-top: 1px solid var(--c-graphite);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-mist);
  flex-wrap: wrap;
  gap: 16px;
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   Misc helpers
   ============================================================ */

.section-rule {
  height: 1px;
  background: var(--c-graphite);
  position: relative;
}

.section-rule::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-cyan);
  box-shadow: 0 0 8px rgba(0, 212, 232, 0.6);
}

.urgency-tag {
  display: inline-block;
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(237, 241, 247, 0.6);
  margin-bottom: 16px;
}

.cta-asym {
  background: var(--c-violet);
  position: relative;
  overflow: hidden;
  padding: 96px 0;
}

.cta-asym-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 48px;
  position: relative;
  z-index: 1;
  align-items: center;
}

.cta-asym-pattern {
  position: absolute;
  top: 0;
  right: -10%;
  width: 70%;
  height: 100%;
  opacity: 0.18;
  pointer-events: none;
  z-index: 0;
}

.cta-asym-pattern svg { width: 100%; height: 100%; }

.cta-asym .h-1 { color: var(--c-coldframe); }
.cta-asym .subhead {
  color: rgba(237, 241, 247, 0.85);
  margin-top: 20px;
  max-width: 560px;
}

.cta-asym .btn-row { margin-top: 40px; justify-content: flex-start; }

@media (max-width: 900px) {
  .cta-asym-grid { grid-template-columns: 1fr; }
  .cta-asym-pattern { width: 100%; opacity: 0.1; }
}

/* Page-level scoped tweaks via data-page-slug */

body[data-page-slug="home"] .hero-headline { letter-spacing: -0.03em; }

